#include <set>
#include <functional>

int main() {
    // Type 1: Ascending order (default)
    std::set<int, std::less<int>> ascending_set = {3, 1, 2};

    // Type 2: Descending order
    std::set<int, std::greater<int>> descending_set = {3, 1, 2};

    // Error: Attempting to assign incompatible types
    // ascending_set = descending_set; // Compilation Error

    // Correct usage: Container stores its comparator type
    using AscendingType = decltype(ascending_set);
    using DescendingType = decltype(descending_set);
    // static_assert(!std::is_same_v<AscendingType, DescendingType>);
}
